// ---------------------------------------------------------------------------
// Local helpers
// ---------------------------------------------------------------------------

/// Calls a PowerPC function with no arguments and keeps its `r3` result.
///
/// # Safety
/// `addr` must point at a PowerPC function returning `u32` and the caller must
/// be running on a PowerPC target.
unsafe fn call0_ret(addr: usize) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn() -> u32);
    f()
}

/// Calls a PowerPC function `(f64, f64) -> ()`.
///
/// Used for the view-object virtual slot `+8` at `0x800E4968`. Ghidra renders
/// both arguments as `(double)` conversions of `float` loads, so the
/// reconstructed call uses `f64`; on the 32-bit PowerPC EABI both arrive in
/// `f1`/`f2`.
///
/// # Safety
/// `addr` must accept two doubles in floating-point registers.
unsafe fn call_f64x2(addr: usize, a: f64, b: f64) {
    let f = crate::platform::guest_fn!(addr, fn(f64, f64));
    f(a, b);
}

/// Reads an `f32` from a big-endian word at `addr`.
///
/// # Safety
/// `addr..addr+4` must be readable.
unsafe fn read_f32(addr: usize) -> f32 {
    f32::from_bits(platform::read_u32(addr))
}

/// Reads an `f64` from two big-endian words at `addr`.
///
/// # Safety
/// `addr..addr+8` must be readable.
unsafe fn read_f64(addr: usize) -> f64 {
    let hi = platform::read_u32(addr) as u64;
    let lo = platform::read_u32(addr + 4) as u64;
    f64::from_bits((hi << 32) | lo)
}

/// Calls a PowerPC function `(f64, f64) -> u32` and keeps its `r3` result.
///
/// The two doubles travel in `f1`/`f2`; the integer result comes back in `r3`.
///
/// # Safety
/// `addr` must accept two doubles and return a word.
unsafe fn call_f64x2_ret(addr: usize, a: f64, b: f64) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f64, f64) -> u32);
    f(a, b)
}

/// Calls a PowerPC function `(f32) -> f32`.
///
/// Used for the sine helper `0x800B2F10` at `0x800EA980`, whose argument and
/// result both travel in floating-point registers. The 32-bit PowerPC EABI
/// keeps the float and integer register files separate, so a Rust
/// `extern "C"` signature with mixed scalar types maps onto it one to one.
///
/// # Safety
/// `addr` must accept one float and return one.
unsafe fn call_f32_arg_ret(addr: usize, a: f32) -> f32 {
    let f = crate::platform::guest_fn!(addr, fn(f32) -> f32);
    f(a)
}

/// Calls a PowerPC function `(pointer) -> f32`.
///
/// Used for the vector-length helper `0x801C14C0` at `0x800E9D10`, which takes
/// the address of a three-float vector and returns its magnitude in `f1`.
///
/// # Safety
/// `a` must point at three readable floats.
unsafe fn call_ptr_f32_ret(addr: usize, a: u32) -> f32 {
    let f = crate::platform::guest_fn!(addr, fn(u32) -> f32);
    f(a)
}

/// Calls a PowerPC function `(f64, f64, f64, pointer) -> ()`.
///
/// Three doubles travel in `f1..f3` and the trailing word in `r3`. This is the
/// shape of the matrix builders (`0x801C0BD0`, `0x801C0C60`, `0x8016A130`).
///
/// # Safety
/// `addr` must accept three doubles plus one integer argument.
unsafe fn call_f64x3_ptr(addr: usize, a: f64, b: f64, c: f64, p: u32) {
    let f = crate::platform::guest_fn!(addr, fn(f64, f64, f64, u32));
    f(a, b, c, p);
}

/// Calls a PowerPC function `(f64 x4, u32, u32) -> ()`.
///
/// Four doubles in `f1..f4`, then two words in `r3`/`r4`. Used by the one-shot
/// colour setup call at `0x800E54E0`.
///
/// # Safety
/// `addr` must accept four doubles plus two integer arguments.
unsafe fn call_f64x4_u32x2(addr: usize, a: f64, b: f64, c: f64, d: f64, x: u32, y: u32) {
    let f = crate::platform::guest_fn!(addr, fn(f64, f64, f64, f64, u32, u32));
    f(a, b, c, d, x, y);
}

/// Calls a PowerPC function `(f64, u32, u32) -> ()`.
///
/// One double in `f1`, then two words in `r3`/`r4`; used by the stepped
/// position writer `0x80167B20` at `0x800EB410`.
///
/// # Safety
/// `addr` must accept one double plus two integer arguments.
unsafe fn call_f64_u32x2(addr: usize, a: f64, p: u32, q: u32) {
    let f = crate::platform::guest_fn!(addr, fn(f64, u32, u32));
    f(a, p, q);
}

/// Calls a PowerPC function `(f64) -> ()`.
///
/// A single double in `f1` and no integer arguments.
///
/// # Safety
/// `addr` must accept one double argument.
unsafe fn call_f64_void(addr: usize, a: f64) {
    let f = crate::platform::guest_fn!(addr, fn(f64));
    f(a);
}

/// Calls a PowerPC function `(u32, u32, u32) -> u64`.
///
/// A 64-bit result comes back split across `r3` (high) and `r4` (low), which is
/// how `0x802DD1EC` - the Metrowerks 64-bit left-shift helper - returns the
/// `1 << index` slot masks used by `0x800E3F20`.
///
/// # Safety
/// `addr` must accept three words and return a 64-bit value.
unsafe fn call3_u64(addr: usize, a: u32, b: u32, c: u32) -> u64 {
    let f = crate::platform::guest_fn!(addr, fn(u32, u32, u32) -> u64);
    f(a, b, c)
}

/// Reads the `dSys_c` object pointer from [`G_D_SYS`].
///
/// # Safety
/// The slot must have been initialized by [`fn_800e48d0`].
unsafe fn d_sys() -> u32 {
    platform::read_u32(G_D_SYS)
}

/// Reads the `dSys_c` child manager at `dSys + 0x4C`.
///
/// `// unknown:` the child's type. The helpers only use its `+4` pointer
/// (a function-pointer table) and its `+8`, `+9`, `+0x14` fields.
///
/// # Safety
/// The child must be non-null and readable.
unsafe fn d_sys_child() -> u32 {
    platform::read_u32(d_sys() as usize + 0x4C)
}

/// Reads the function-pointer table at `child + 4` and one entry from it.
///
/// `// inferred:` `child + 4` points at a table of callbacks; the step helpers
/// call entries `+8`, `+0xC`, `+0x10` and `+0x14`.
///
/// # Safety
/// The child and the table must be readable.
unsafe fn child_callback(slot: usize) -> usize {
    let table = platform::read_u32(d_sys_child() as usize + 4);
    platform::read_u32(table as usize + slot) as usize
}

/// Reads one vtable slot of the `dSys_c` object.
///
/// # Safety
/// The object's first word must be a readable vtable.
unsafe fn d_sys_vtable_slot(slot: usize) -> usize {
    let vtable = platform::read_u32(d_sys() as usize);
    platform::read_u32(vtable as usize + slot) as usize
}

// ---------------------------------------------------------------------------
// 0x800E45F0 - two large blocks
// ---------------------------------------------------------------------------

/// Allocates the 1 MiB MEM1 block and the 2.5 MiB MEM2 block used by the
/// engine.
///
/// Calls `0x8016E630(size, heap, tag, 0x20, flags)` twice and stores the two
/// results in [`G_BLOCK_1M`] and [`G_BLOCK_25M`]. The second call uses flag `4`;
/// the first uses `0`.
///
/// # Original
/// - Ghidra: `FUN_800e45f0` at `0x800E45F0` (108 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800e45f0_FUN_800e45f0.c`
///
/// # Arguments
/// * `mem1` - `RootHeapMEM1` handle, forwarded as argument 2 of the 1 MiB call.
/// * `mem2` - `RootHeapMEM2` handle, forwarded as argument 2 of the 2.5 MiB
///   call.
///
/// # Returns
/// Nothing; both results live in SDA.
///
/// # Side effects
/// Two allocations, two SDA stores.
///
/// # Safety
/// Both heap handles must be live. `0x8016E630` must accept the five-argument
/// call shape shown in the evidence.
///
/// # Confidence
/// high - the two calls and both stores are explicit; only the meaning of the
/// tag pointers is unknown.
pub unsafe fn fn_800e45f0(mem1: u32, mem2: u32) {
    let block_1m = platform::call5(
        FN_8016E630,
        0x10_0000, // 1 MiB
        mem1,
        TAG_BLOCK_1M as u32,
        0x20,
        0,
    );
    platform::write_u32(G_BLOCK_1M, block_1m);

    let block_25m = platform::call5(
        FN_8016E630,
        0x28_0000, // 2.5 MiB
        mem2,
        TAG_BLOCK_25M as u32,
        0x20,
        4,
    );
    platform::write_u32(G_BLOCK_25M, block_25m);
}

// ---------------------------------------------------------------------------
// 0x800E4660 / 0x800E4680 / 0x800E46E0 / 0x800E4740 - dSys frame steps
// ---------------------------------------------------------------------------

/// Runs the `dSys` begin-of-frame step.
///
/// Calls the child callback at `child+4 -> +8`, then the `dSys` vtable slot
/// `+0x24` (no arguments).
///
/// # Original
/// - Ghidra: `FUN_800e46e0` at `0x800E46E0` (72 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800e46e0_FUN_800e46e0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Two indirect calls. Their targets are opaque.
///
/// # Safety
/// The `dSys` object, its child and the child's callback table must all be
/// valid. The original performs no null checks.
///
/// # Confidence
/// high for both call expressions; low for the callbacks' roles.
pub unsafe fn fn_800e46e0() {
    platform::call0(child_callback(8));
    platform::call0(d_sys_vtable_slot(0x24));
}

/// Runs the `dSys` mid-frame step: child callback `+0xC`.
///
/// # Original
/// - Ghidra: `FUN_800e4660` at `0x800E4660` (24 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800e4660_FUN_800e4660.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// One indirect call.
///
/// # Safety
/// The `dSys` object, its child and the callback table must be valid.
///
/// # Confidence
/// high for the call expression; low for the callback's role.
pub unsafe fn fn_800e4660() {
    platform::call0(child_callback(0xC));
}

/// Runs the `dSys` flag step.
///
/// Sets three consecutive bytes at `0x8042A09C..0x8042A09E` to `1` when they
/// are still `0`, then calls child callback `+0x10`.
///
/// # Original
/// - Ghidra: `FUN_800e4680` at `0x800E4680` (84 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800e4680_FUN_800e4680.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Up to three byte stores and one indirect call.
///
/// # Safety
/// The three bytes are fixed SDA locations; the callback table must be valid.
///
/// # Confidence
/// high - the three stores are explicit; the byte meanings are unknown.
pub unsafe fn fn_800e4680() {
    // `r13 - 0x55E4` = 0x8042A09C, then +1, +2. `// unknown:` what each flag
    // gates; the write is one-shot (only 0 -> 1).
    for addr in (SDA_BASE - 0x55E4)..=(SDA_BASE - 0x55E2) {
        if platform::read_u8(addr) == 0 {
            platform::write_u8(addr, 1);
        }
    }
    platform::call0(child_callback(0x10));
}

/// Runs the `dSys` end-of-frame step.
///
/// Calls child callback `+0x14`, then the `dSys` vtable slot `+0x28`, with no
/// arguments.
///
/// # Original
/// - Ghidra: `FUN_800e4740` at `0x800E4740` (72 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800e4740_FUN_800e4740.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
