/// # Original
/// - Ghidra: `FUN_800e6ef0` at `0x800E6EF0` (328 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800e6ef0_FUN_800e6ef0.c`
///
/// # Arguments
/// - `this`: message object; the slot block is addressed `this + slot * 0x28`.
/// - `mode`: pointer to one byte added to the tag.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Eight word/float stores in the slot, three `u16` stores in the message,
/// plus the length call.
///
/// # Safety
/// The whole slot block, the layout object, the surface and the frame record
/// must be readable; `mode` must point at one byte.
///
/// # Confidence
/// medium - the arithmetic is literal, but the slot's field roles and the
/// double-dereferenced [`G_DISPLAY_METRICS`] record are inferred.
pub unsafe fn fn_800e6ef0(this: usize, mode: usize) {
    let context = text_context();
    let frame = platform::read_u32(context + 0x3DC) as usize;
    let surface = platform::read_u32(context + 0x3E0) as usize;
    let slot = platform::read_u32(context + 0x3C8) & 0xFFFF;
    let base = this + (slot as usize) * 0x28;

    platform::write_u32(base + 0x3C, frame as u32);
    platform::write_u32(base + 0x40, platform::read_u32(frame + 0x4C));
    platform::write_u32(base + 0x44, platform::read_u32(frame + 0x50));
    platform::write_u32(base + 0x48, surface as u32);

    let zero = read_f32(F_STATE_ZERO);
    let mut width = (read_f32(surface + 0x3C) - read_f32(surface + 0x34))
        / read_f32(surface + 0x44);
    let mut height = (read_f32(surface + 0x40) - read_f32(surface + 0x38))
        / read_f32(surface + 0x48);
    if width < zero {
        width *= read_f32(F_SIGN_FLIP);
    }
    if height < zero {
        height *= read_f32(F_SIGN_FLIP);
    }

    // observed: `**(int **)(r13 - 0x5200)` - the metrics record is reached
    // through one extra pointer.
    let metrics = platform::read_u32(platform::read_u32(G_DISPLAY_METRICS) as usize) as usize;
    let bias = read_f64(D_UNSIGNED_BIAS);
    let x = f64::from_bits((0x4330_0000u64 << 32) | platform::read_u16(metrics + 4) as u64) - bias;
    let y = f64::from_bits((0x4330_0000u64 << 32) | platform::read_u16(metrics + 6) as u64) - bias;
    platform::write_f32(base + 0x34, (x as f32) / width);
    platform::write_f32(base + 0x38, (y as f32) / height);

    let flag = platform::read_u8(mode);
    fn_800e6970(this);
    platform::write_u16(this + 4, 0xF);
    platform::write_u16(
        this + 6,
        (((slot << 4) as u32) | (flag as u32).wrapping_add(1)) as u16,
    );
    platform::call1(FN_802E441C, (this + 4) as u32);
}

/// Builds a message with the style chosen by a mode byte.
