///
/// # Returns
/// Nothing.
///
/// # Side effects
/// One encoder call and one length call.
///
/// # Safety
/// `this + 4..this + 0x24` must be writable and the context must be live.
///
/// # Confidence
/// high - the handle offset and the encoder arguments are literal.
pub unsafe fn fn_800e7060(this: usize) {
    let handle = platform::read_u32(text_context() + 0x3C4);
    platform::call5(FN_800CDDB0, handle, (this + 4) as u32, 0x10, 1, 0);
    platform::call1(FN_802E441C, (this + 4) as u32);
}

/// Builds the two-part label: a 4-slot prefix and a 4-slot decimal tail.
///
/// The `0x5F` word at `+0xC` separates the two halves; the second encoder
/// starts at `+0xE` with only 0xC bytes of room.
///
/// # Original
/// - Ghidra: `FUN_800e70b0` at `0x800E70B0` (116 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800e70b0_FUN_800e70b0.c`
///
/// # Arguments
/// - `this`: message object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Two encoder calls, one `u16` store and one length call.
///
/// # Safety
/// `this + 4..this + 0x1A` must be writable.
///
/// # Confidence
/// high - both handles, the separator and the two widths are literal.
pub unsafe fn fn_800e70b0(this: usize) {
    let context = text_context();
    let prefix = platform::read_u32(context + 0x3D0);
    let tail = platform::read_u32(context + 0x3D4);
    platform::call5(FN_800CDC70, prefix, (this + 4) as u32, 0x10, 4, 0);
    platform::write_u16(this + 0xC, 0x5F);
    platform::call5(FN_800CDC70, tail, (this + 0xE) as u32, 0xC, 4, 0);
    platform::call1(FN_802E441C, (this + 4) as u32);
}

/// Clears the message and re-encodes it from the handle at `context + 0x3CC`.
