    let mut alternate_name = crate::platform::GuestLocal::new( [0u8; 16]);
    platform::call4(
        FN_802E16E8,
        name.as_mut_ptr() as u32,
        0x10,
        G_NAME_6E90 as u32,
        platform::read_u32(param_1 + 0x7D4) + 1,
    );
    platform::call4(
        FN_802E16E8,
        alternate_name.as_mut_ptr() as u32,
        0x10,
        G_NAME_6E90 as u32,
        platform::read_u32(param_1 + 0x7D4) + 1,
    );

    let object = platform::call3(
        FN_800DF180,
        platform::read_u32(G_RESOURCE_ROOT) + 4,
        name.as_ptr() as u32,
        STR_G3D_MODEL_BRRES as u32,
    );
    platform::write_u32(param_1 + 4, object);

    let mut handle = crate::platform::GuestLocal::new( [platform::call2(
        FN_80239E30,
        (param_1 + 4) as u32,
        alternate_name.as_ptr() as u32,
    ); 1]);
