// ---------------------------------------------------------------------------
// Wave 103 constants
// ---------------------------------------------------------------------------

/// `r2 - 0x6388` = `0x8042CCF8`: the `2^52` bias of the unsigned widening.
///
/// `// observed:` every `CONCAT44(0x43300000, x)` in the Wave 103 bodies is the
/// CodeWarrior unsigned-int-to-double idiom, so this word is the bias itself.
const F_BIAS_6388: usize = R2_BASE - 0x6388; // 0x8042CCF8

/// `r2 - 0x63E0` = `0x8042CCA0`: second `2^52` bias, used by `0x800E28A0`.
const F_BIAS_63E0: usize = R2_BASE - 0x63E0; // 0x8042CCA0

/// `r2 - 0x6368` = `0x8042CD18`: per-step scale of `0x800E6090`/`0x800E63A0`.
const F_CONST_6368: usize = R2_BASE - 0x6368; // 0x8042CD18

/// `r2 - 0x63B0` = `0x8042CCD0`: word written into every reset sprite slot of
/// `0x800E3BA0`.
const F_CONST_63B0: usize = R2_BASE - 0x63B0; // 0x8042CCD0

/// `r2 - 0x63BC` = `0x8042CCC4`: first parametric value of the mesh decoders.
const F_CONST_63BC: usize = R2_BASE - 0x63BC; // 0x8042CCC4

/// `r2 - 0x63CC` = `0x8042CCB4`: divisor of the scaled metric in `0x800E28A0`.
const F_CONST_63CC: usize = R2_BASE - 0x63CC; // 0x8042CCB4

/// `r13 - 0x5700` = `0x80429F80`: application flag word gating `0x800E20A0`.
///
/// `// inferred:` the two tested bits (`0x10`, `0x40`) are readiness flags of the
/// pause/notification path; the export only shows the masks.
const G_FLAGS_5700: usize = SDA_BASE - 0x5700; // 0x80429F80

/// `r13 - 0x56D0` = `0x80429FB0`: owner object passed to `0x800CEA70`.
const G_56D0: usize = SDA_BASE - 0x56D0; // 0x80429FB0

/// `r13 - 0x5920` = `0x80429D60`: sound object passed to `0x80198C30`.
const G_SOUND_5920: usize = SDA_BASE - 0x5920; // 0x80429D60

/// `r13 - 0x55B8` = `0x8042A0C8`: "use the zero gain" byte of `0x800E63A0`.
const G_MODE_55B8: usize = SDA_BASE - 0x55B8; // 0x8042A0C8

/// `r13 - 0x57E8` = `0x80429E98`: pointer to the current stage object.
const G_STAGE_57E8: usize = SDA_BASE - 0x57E8; // 0x80429E98

/// `r13 - 0x5414` = `0x8042A26C`: audio-library handle of `0x800EF570`.
const G_AUDIO_5414: usize = SDA_BASE - 0x5414; // 0x8042A26C

/// `r13 - 0x6F10` = `0x80428770`: resource-name prefix compared by
/// `0x800EEAE0`.
const G_NAME_6F10: usize = SDA_BASE - 0x6F10; // 0x80428770

/// `0x802F2EE0`: ten-entry word table indexed by the notification index.
const TBL_802F2EE0: usize = 0x802F_2EE0;

/// `0x802F2FC8`: four-entry table of sign-flipped `f32` corrections.
const TBL_802F2FC8: usize = 0x802F_2FC8;

/// `0x8031BB08`: table of sound-name pointers indexed by the effect index.
const TBL_8031BB08: usize = 0x8031_BB08;

/// `0x8031BB20`: table of resource-name pointers indexed by the effect index.
const TBL_8031BB20: usize = 0x8031_BB20;

/// `0x803504EE`: `u16` span used by the scaled metric of `0x800E28A0`.
const G_803504EE: usize = 0x8035_04EE;

/// `0x800CEA70(owner, key, value)` - notification dispatch.
const FN_800CEA70: usize = 0x800C_EA70;

/// `0x8006A4B0(dst, src)` - copies one two-float vector.
const FN_8006A4B0: usize = 0x8006_A4B0;

/// `0x80198C30(sound, id, vector, extra)` - posts one sound event.
const FN_80198C30: usize = 0x8019_8C30;

/// `0x80165520(track, keys, count, name, flag)` - starts a keyed track build.
const FN_80165520: usize = 0x8016_5520;

/// `0x801656C0(offset, track, index, record)` - appends one keyed record.
const FN_801656C0: usize = 0x8016_56C0;

/// `0x800F1BE0()` - "is the pending notification still live" probe.
const FN_800F1BE0: usize = 0x800F_1BE0;

/// `0x800F1BD0(handle)` - converts a notification handle into a record name.
const FN_800F1BD0: usize = 0x800F_1BD0;

/// `0x8025C560(record, flag)` - builds the transform of one effect record.
const FN_8025C560: usize = 0x8025_C560;

/// `0x8023D3C0(values, count, selector)` - writes one selector pair.
const FN_8023D3C0: usize = 0x8023_D3C0;

/// `0x80103410(owner, id, target, name, a, b)` - creates an effect.
const FN_80103410: usize = 0x8010_3410;

/// `0x801034E0(owner)` - releases the effect held by `owner`.
const FN_801034E0: usize = 0x8010_34E0;

/// `0x802307E0(record, flag)` - releases one stack effect record.
const FN_802307E0: usize = 0x8023_07E0;

/// `0x800B1310(id)` - resolves the effect manager object.
const FN_800B1310: usize = 0x800B_1310;

/// `0x8022D3C0(value, record)` - sets the single float of a stack record.
const FN_8022D3C0: usize = 0x8022_D3C0;

/// `0x800E2D70(t)` - first quadratic weight. The body lives in
/// `engine::frame` (`curve_weight_neg_square`), so it is called by address.
const FN_800E2D70: usize = 0x800E_2D70;

/// `0x800E2D90(t)` - second quadratic weight, also in `engine::frame`
/// (`curve_weight_product`).
const FN_800E2D90: usize = 0x800E_2D90;

/// Calls a PowerPC function `(f64, u32, u32, u32) -> ()`.
///
/// The double travels in `f1`; the three words in `r3`/`r4`/`r5`. This is the
/// shape of `0x801656C0`, which Ghidra prints as `(double, ptr, int, ptr)`.
///
/// # Safety
/// `addr` must accept one double plus three integer arguments.
unsafe fn call_f64_u32x3(addr: usize, a: f64, b: u32, c: u32, d: u32) {
    let f = crate::platform::guest_fn!(addr, fn(f64, u32, u32, u32));
    f(a, b, c, d);
}

/// Calls a PowerPC function `(f64, u32) -> ()`.
///
/// # Safety
/// `addr` must accept one double and one integer argument.
unsafe fn call_f64_u32(addr: usize, a: f64, b: u32) {
    let f = crate::platform::guest_fn!(addr, fn(f64, u32));
    f(a, b);
}

/// Calls a PowerPC function `(f64, f64, u32, u32) -> u32`.
///
/// # Safety
/// `addr` must accept two doubles plus two words and return a word.
unsafe fn call_f64x2_u32x2_ret(addr: usize, a: f64, b: f64, c: u32, d: u32) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f64, f64, u32, u32) -> u32);
    f(a, b, c, d)
}

/// Calls a PowerPC function `(f64, pointer) -> ()`.
///
/// # Safety
/// `addr` must accept one double plus one integer argument.
unsafe fn call_f64_ptr(addr: usize, a: f64, p: u32) {
    let f = crate::platform::guest_fn!(addr, fn(f64, u32));
    f(a, p);
}

/// Calls a PowerPC function `(u64, f64, u32, u32) -> ()`.
///
/// The `u64` travels in `r3`/`r4`, the double in `f1`, the two words in
/// `r5`/`r6`. `0x80166310` is printed with this argument list at `0x800EF890`
/// and `0x800EF940`, so the mixed layout is transcribed rather than reconciled
/// with the `(f64, u32, u32)` call sites of the same callee elsewhere.
///
/// # Safety
/// `addr` must accept the mixed argument list shown above.
unsafe fn call_u64_f64_u32x2(addr: usize, a: u64, b: f64, c: u32, d: u32) {
    let f = crate::platform::guest_fn!(addr, fn(u64, f64, u32, u32));
    f(a, b, c, d);
}

// ---------------------------------------------------------------------------
// 0x800E20A0 - notification pose push
// ---------------------------------------------------------------------------

/// Pushes a two-float notification position derived from the cursor object.
///
/// The incoming `handle` supplies the notification object in its **low** word
/// (unlike [`fn_800eee70`], where the object is the first argument) and a key
/// word in its high word. The two incoming floats are biased by the object's
/// `+0xAC`/`+0xB0` offsets and forwarded to the band pass
/// [`fn_800e1f80`]. When both [`G_FLAGS_5700`] bits `0x10`/`0x40` are set and
/// the object's `+0x38C` byte is `3`, a ten-entry table is consulted; a live
/// entry posts `0x800CEA70` and, unless the current id is `0x22`, one
/// `0x80198C30` sound event with the copied vector.
///
/// # Original
/// - Ghidra: `FUN_800e20a0` at `0x800E20A0` (380 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800e20a0_FUN_800e20a0.c`
/// - Removed: the modelled `0x802DCD6C` call. It is `_savegpr_25` (register
///   spill only), so the pair is the incoming `r3:r4`, i.e. `handle`.
///
/// # Arguments
/// - `handle`: 64-bit first argument, printed as `undefined8`; its low half is
///   the notification object, its high half is forwarded to [`fn_800e1f80`].
/// - `x`, `y`: the two incoming floats (`f1`/`f2` in the original).
/// - `index`: table index, also forwarded to [`fn_800e1f80`].
/// - `param_6`: notification key.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Two float stores on the stack, up to two calls per live table entry, one
/// band pass and its two virtual/band calls.
///
/// # Safety
/// The notification object must be live through `+0x4FC`, the stage object at
/// [`G_STAGE_57E8`] readable, and `index` must stay inside the ten-entry table.
///
/// # Confidence
/// medium - every guard, table read and call is literal; the second incoming
/// float is only reachable through Ghidra's `extraout_f1`, and the two unused
/// printed arguments are dropped from the signature.
pub unsafe fn fn_800e20a0(handle: u64, x: f64, y: f64, index: i32, param_6: u32) {
    let base = handle as u32 as usize;
    let key = (handle >> 32) as u32;

    let mut point = crate::platform::GuestLocal::new( [0f32; 2]);
    point[1] = (y + read_f32(base + 0xB0) as f64) as f32;
    point[0] = (x + read_f32(base + 0xAC) as f64) as f32;
    // observed: `local_58 = *(r2 - 0x63F0)` is stored but never read; omitted.

    let flags = platform::read_u32(G_FLAGS_5700);
    if (flags & 0x10) != 0 && (flags & 0x40) != 0 && platform::read_u8(base + 0x38C) == 3 {
        let mut table = [0u32; 10];
        for (slot, word) in table.iter_mut().enumerate() {
            *word = platform::read_u32(TBL_802F2EE0 + slot * 4);
        }
        let id = platform::read_u16(base + 8);
        let armed = (platform::read_u32(base + 0x4FC) & 0x10) != 0
            || id == 0x22
            || id == 0x4B
            || id == 0x4C;
        let live = armed && table[index as usize] != 0;
        if live {
            platform::call3(
                FN_800CEA70,
                platform::read_u32(G_56D0),
                param_6,
                table[index as usize],
            );
            if platform::read_u16(base + 8) != 0x22 {
                let mut copy = crate::platform::GuestLocal::new( [0u32; 2]);
                platform::call2(
                    FN_8006A4B0,
                    copy.as_mut_ptr() as u32,
                    point.as_ptr() as u32,
                );
                platform::call4(
                    FN_80198C30,
                    platform::read_u32(G_SOUND_5920),
                    0x520,
                    copy.as_mut_ptr() as u32,
                    0,
                );
            }
        }
    }

    fn_800e1f80(key, point.as_ptr() as u32, index as u32, param_6 as i32, 1);
}

// ---------------------------------------------------------------------------
// 0x800E28A0 - packed pair of the two corrected display metrics
// ---------------------------------------------------------------------------

/// Returns the two display metrics as one packed pair of `f32` halves.
///
/// The metrics are the `u16` fields `+4`/`+6` of the display record, widened
/// with the `2^52` bias. `0x801DD1D0` selects the mode: when it returns zero the
/// second value is re-derived from the first through [`F_CONST_63CC`] and the
/// `u16` span at [`G_803504EE`]; otherwise both raw metrics are kept. A
/// four-entry table of sign-flipped floats at [`TBL_802F2FC8`] then corrects
/// each value in the low two bits.
///
/// # Original
/// - Ghidra: `FUN_800e28a0` at `0x800E28A0` (420 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800e28a0_FUN_800e28a0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// A `u64` whose high word is the first `f32` and whose low word the second,
/// exactly as the export's `CONCAT44` shows.
///
/// # Side effects
/// One mode probe and two table reads; no stores.
///
/// # Safety
/// [`G_DISPLAY_5200`] must point at a live record and both tables readable.
///
/// # Confidence
/// medium - the guards, widenings and both table corrections are literal; the
/// `dVar4` reuse in the export is resolved as "second value", which is what the
/// final `CONCAT44` consumes.
pub unsafe fn fn_800e28a0() -> u64 {
    let display = platform::read_u32(G_DISPLAY_5200) as usize;
    let record = platform::read_u32(display) as usize;
    let bias = read_f64(F_BIAS_63E8);
    let first = ((platform::read_u16(record + 4) as u32 as f64) - bias) as f32 as f64;
    let second = ((platform::read_u16(record + 6) as u32 as f64) - bias) as f32 as f64;

    let first_value;
    let second_value;
    if call0_ret(THUNK_801DD1D0) as u8 == 0 {
        first_value = ((first as i32 & 0xFFFF) as f64) - bias;
        // observed: `(f32)(first / divisor) * (f32)(span - bias)`, truncated and
        // masked back to 16 bits before the widening.
        let quotient = (first / read_f32(F_CONST_63CC) as f64) as f32;
        let span = ((platform::read_u16(G_803504EE) as u32 as f64) - bias) as f32;
        second_value = ((((quotient * span) as i32) & 0xFFFF) as f64) - bias;
    } else {
        first_value = ((first as i32 & 0xFFFF) as f64) - bias;
        second_value = ((second as i32 & 0xFFFF) as f64) - bias;
    }

    let low_bias = read_f64(F_BIAS_63E0);
    let x = (first_value as f32)
        + ((platform::read_u32(TBL_802F2FC8 + ((first_value as i32 & 3) as usize) * 4)
            ^ 0x8000_0000) as f64
            - low_bias) as f32;
    let y = (second_value as f32)
        + ((platform::read_u32(TBL_802F2FC8 + ((second_value as i32 & 3) as usize) * 4)
            ^ 0x8000_0000) as f64
            - low_bias) as f32;

    ((x.to_bits() as u64) << 32) | y.to_bits() as u64
}

// ---------------------------------------------------------------------------
// 0x800E2DE0..0x800E3160 - mesh strip decoders
// ---------------------------------------------------------------------------

/// Decodes one three-float strip into the destination block.
///
/// Walks the incoming pointer pair (`r3:r4`) in strides of six floats and
/// calls [`fn_800e3040`] for each step, then finishes the strip according to
/// `mode`: `1` writes the scaled sum of the two last vertices, `0` appends two
/// further transformed vertices and copies the original destination point.
///
/// # Original
/// - Ghidra: `FUN_800e2de0` at `0x800E2DE0` (304 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800e2de0_FUN_800e2de0.c`
/// - Removed: the modelled `0x802DCD68`/`0x802DCDB4` calls. They are the
///   `_savegpr_24`/`_restgpr_24` compiler helpers (register spill/restore
///   only), so the bounds are the incoming `r3:r4`.
///
/// # Arguments
/// - `start`, `end`: the incoming pointer pair (`r3:r4`); the body walks floats
///   between them.
/// - `dst`: first destination float; the body advances its own cursor.
/// - `mode`: `0` or `1` selects the finishing branch.
/// - `count`: number of vertices handed to each [`fn_800e3040`] call.
/// - `step`: parametric increment, printed as the leftover `f1` value.
///
/// # Returns
/// Nothing; the finished cursor is an internal value.
///
/// # Side effects
/// `count * 3` float stores per strip step plus the finishing branch.
///
/// # Safety
/// The incoming pair must bound a readable float array and `dst` must have
/// room for every strip written.
///
/// # Confidence
/// medium - the loop, bounds and branch bodies are literal; `step` is the
/// `extraout_f1` the export threads through unchanged.
pub unsafe fn fn_800e2de0(
    start: u32,
    end: u32,
    dst: usize,
    mode: i32,
    count: i32,
    step: f64,
) {
    let start = start as usize;
    let end = end as usize;

    let mut out = dst;
    let mut next_start = start;
    let mut previous = start;
    let mut current = start + 12;
    let mut cursor = start + 24;
    while cursor < end {
        current = previous + 12;
        out = fn_800e3040(
            next_start as u32,
            previous as u32,
            cursor,
            out,
            count,
            step,
        ) as usize;
        next_start += 12;
        previous = current;
        cursor += 12;
    }

    if mode == 1 {
        let factor = read_f32(F_QUAD_SCALE);
        platform::write_f32(out, factor * (read_f32(next_start) + read_f32(current)));
        platform::write_f32(
            out + 4,
            factor * (read_f32(next_start + 4) + read_f32(previous + 16)),
        );
        out += 12;
    } else if mode == 0 {
        let first = fn_800e3040(
            next_start as u32,
            current as u32,
            start,
            out,
            count,
            step,
        ) as usize;
        out = fn_800e3040(
            current as u32,
            start as u32,
            start + 12,
            first,
            count,
            step,
        ) as usize;
        platform::write_f32(out, read_f32(dst));
        platform::write_f32(out + 4, read_f32(dst + 4));
        platform::write_f32(out + 8, read_f32(dst + 8));
    }
}

/// Decodes one two-float strip into the destination block.
///
/// The two-float twin of [`fn_800e2de0`]: it walks the incoming pair (`r3:r4`)
/// in strides of four floats, calls [`fn_800e3160`], and finishes with the same
/// `mode` branches two floats wide.
///
/// # Original
/// - Ghidra: `FUN_800e2f10` at `0x800E2F10` (296 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800e2f10_FUN_800e2f10.c`
/// - Removed: the modelled `0x802DCD68`/`0x802DCDB4` calls. They are the
///   `_savegpr_24`/`_restgpr_24` compiler helpers (register spill/restore
///   only), so the bounds are the incoming `r3:r4`.
///
/// # Arguments
/// As [`fn_800e2de0`].
///
/// # Returns
/// Nothing; the finished cursor is an internal value.
///
/// # Side effects
/// `count * 2` float stores per strip step plus the finishing branch.
///
/// # Safety
/// As [`fn_800e2de0`], two floats per vertex.
///
/// # Confidence
/// medium - same shape as [`fn_800e2de0`]; only the stride and the callee
/// differ.
pub unsafe fn fn_800e2f10(
    start: u32,
    end: u32,
    dst: usize,
    mode: i32,
    count: i32,
    step: f64,
) {
    let start = start as usize;
    let end = end as usize;

    let mut out = dst;
    let mut next_start = start;
    let mut previous = start;
    let mut current = start + 8;
    let mut cursor = start + 16;
    while cursor < end {
        current = previous + 8;
        out = fn_800e3160(
            next_start as u32,
            previous as u32,
            cursor,
            out,
            count,
            step,
        ) as usize;
        next_start += 8;
        previous = current;
        cursor += 8;
    }

    if mode == 1 {
        let factor = read_f32(F_QUAD_SCALE);
        platform::write_f32(out, factor * (read_f32(next_start) + read_f32(current)));
        platform::write_f32(
            out + 4,
            factor * (read_f32(next_start + 4) + read_f32(current + 4)),
        );
        out += 8;
    } else if mode == 0 {
        let first = fn_800e3160(
            next_start as u32,
            current as u32,
            start,
            out,
            count,
            step,
        ) as usize;
        out = fn_800e3160(
            current as u32,
            start as u32,
            start + 8,
            first,
            count,
            step,
        ) as usize;
        platform::write_f32(out, read_f32(dst));
        platform::write_f32(out + 4, read_f32(dst + 4));
    }
}

/// Writes one transformed three-float vertex range.
///
/// For every entry the body reads the first two floats, evaluates the three
/// quadratic weights at the running parameter with `0x800E2D70`, `0x800E2D90`
/// and `0x800E2DB0`, and combines them with the two scale pointers of the
/// `0x802DCD74` pair through the six-term dot product `0x800E2DC0`. Two floats
/// are stored and the destination advances by three, so the third component is
/// left untouched.
///
/// # Original
/// - Ghidra: `FUN_800e3040` at `0x800E3040` (276 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800e3040_FUN_800e3040.c`
/// - Removed: the modelled `0x802DCD74`/`0x802DCDC0` calls. They are the
///   `_savegpr_27`/`_restgpr_27` compiler helpers (register spill/restore
///   only), so the two scale pointers are the incoming `r3`/`r4`.
///
/// # Arguments
/// - `scale`: first scale pointer (incoming `r3`).
/// - `origin`: second scale pointer (incoming `r4`).
/// - `src`: source float triples.
/// - `dst`: destination float triples.
/// - `count`: number of triples to write.
/// - `step`: parametric increment (`f1` in the original).
///
/// # Returns
/// The advanced destination pointer.
///
/// # Side effects
/// Two float stores per entry; no other memory is touched.
///
/// # Safety
/// `src..src + count*12` and `dst..dst + count*12` must be readable/writable and
/// both incoming scale pointers must point at readable floats.
///
/// # Confidence
/// medium - the arithmetic, stores and stride are literal; the `f1` step
/// follows from the six-value call site, whose first printed value is the
/// floating-point register.
pub unsafe fn fn_800e3040(
    scale: u32,
    origin: u32,
    src: usize,
    dst: usize,
    count: i32,
    step: f64,
) -> u32 {
    let scale = scale as usize;
    let origin = origin as usize;

    let end = dst + count as usize * 12;
    let mut parameter = read_f32(F_CONST_63BC);
    let mut out = dst;
    loop {
        let at = parameter as f64;
        let weight_a = call_f64_arg_ret(FN_800E2D70, at);
        let weight_b = call_f64_arg_ret(FN_800E2D90, at);
        let weight_c = fn_800e2db0(at);
        let x = fn_800e2dc0(
            read_f32(scale) as f64,
            read_f32(origin) as f64,
            read_f32(src) as f64,
            weight_a,
            weight_b,
            weight_c,
        );
        platform::write_f32(out, x as f32);
        let y = fn_800e2dc0(
            read_f32(scale + 4) as f64,
            read_f32(origin + 4) as f64,
            read_f32(src + 4) as f64,
            weight_a,
            weight_b,
            weight_c,
        );
        platform::write_f32(out + 4, y as f32);
        out += 12;
        parameter = (at + step) as f32;
        if out >= end {
            break;
        }
    }
    out as u32
}

/// Writes one transformed two-float vertex range.
///
/// The two-float twin of [`fn_800e3040`]: two floats per entry, the destination
/// advances by two and the same three quadratic weights are used.
///
/// # Original
/// - Ghidra: `FUN_800e3160` at `0x800E3160` (276 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800e3160_FUN_800e3160.c`
/// - Removed: the modelled `0x802DCD74`/`0x802DCDC0` calls. They are the
///   `_savegpr_27`/`_restgpr_27` compiler helpers (register spill/restore
///   only), so the two scale pointers are the incoming `r3`/`r4`.
///
/// # Arguments
