const F_CONST_6370: usize = R2_BASE - 0x6370; // 0x8042CD10

/// `r2 - 0x636C` = `0x8042CD14`: 0.6, the pair factor of the record copies.
const F_CONST_636C: usize = R2_BASE - 0x636C; // 0x8042CD14

