/// `0x8022D4A0` - object query returning one `f32` in `f1`.
const FN_8022D4A0: usize = 0x8022_D4A0;

/// `0x8022D500` - object query returning one `f32` in `f1`.
const FN_8022D500: usize = 0x8022_D500;

/// `0x8022D560` - record query returning one `f32` in `f1`.
const FN_8022D560: usize = 0x8022_D560;

/// `0x8022D5F0` - record submit with one `u32` channel word.
const FN_8022D5F0: usize = 0x8022_D5F0;

/// `0x802310D0` - measures one glyph run: `(object, end, count) -> f32`.
const FN_802310D0: usize = 0x8023_10D0;

/// `0x80231870` - rewinds one glyph run: `(object, end, count) -> ()`.
const FN_80231870: usize = 0x8023_1870;

/// `0x801C9C60` - draws one quad from four corner values.
const FN_801C9C60: usize = 0x801C_9C60;

/// `0x801C9CD0` - reads the four corner values of the current glyph cell.
const FN_801C9CD0: usize = 0x801C_9CD0;

/// Calls a PowerPC function `(f64) -> u32`.
