/// # Safety
/// `addr` must accept one double in `f1` and return a word in `r3`.
unsafe fn call_f64_ret_u32(addr: usize, a: f64) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f64) -> u32);
    f(a)
}

/// Calls a PowerPC function `(u32, u32, u32) -> f32`.
