/// `r13 - 0x6DC0` = `0x804288C0`: archive handle compared by `0x802E1BD0`.
const G_ARCHIVE_6DC0_F: usize = SDA_BASE - 0x6DC0; // 0x804288C0

/// `r13 - 0x5560` = `0x8042A120`: id written by [`fn_800f2680`].
