/// `r2 - 0x6154` = `0x8042CF2C`: image float `-478.0`.
const F_2680_Z_F: usize = R2_BASE - 0x6154; // 0x8042CF2C

/// `r2 - 0x6114` = `0x8042CF6C`: image word `23`, stored at `0x8031BBFC`.
const G_WORD_2680_HEAD_F: usize = R2_BASE - 0x6114; // 0x8042CF6C

