    platform::write_f32(param_1 as usize + 0x10, read_f32(param_3 as usize + 4));
    platform::write_f32(param_1 as usize + 0x14, read_f32(param_3 as usize + 8));
    platform::write_u32(param_1 as usize + 0x4C, param_4);
