/// - Evidence: `work/ghidra/main-gb/export/800f5130_FUN_800f5130.c`
/// - Removed: both modelled `0x802DCDB8` epilogue calls. They are the outlined
///   `_restgpr_25` helper; the early exit now returns directly and the tail one
///   is dropped.
///
/// # Arguments
/// * `param_1` - manager object: name count at `+0x10`, table at `+0x15018`.
/// * `param_2` - the CSV text buffer.
/// * `param_3` - address of the byte cursor into that buffer.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Advances the cursor and may OR one flag bit into `+0x1502C` of the current
/// name-table slot.
///
/// # Safety
/// `param_2` must be a NUL-terminated buffer reachable through the cursor,
/// `param_3` must be a writable word and the manager's table must be writable.
///
/// # Confidence
/// medium - every character test, the cursor arithmetic and the three
/// compares are literal in the disassembly; the manager/table roles and the
/// `A`/`B`/`C` meaning are `// inferred:`.
pub unsafe fn fn_800f5130(param_1: u32, param_2: u32, param_3: u32) {
    let manager = param_1 as usize;
    let source = param_2 as usize;
    let cursor = param_3 as usize;

    // observed: `extsb` before both tests, so the byte is compared signed.
    let first = platform::read_u8(source + platform::read_u32(cursor) as usize) as i8;
    if first == 0x0D
        && platform::read_u8(source + platform::read_u32(cursor) as usize + 1) == 0x0A
    {
        return;
    }

    let mut quoted = false;
    if first == 0x22 {
        quoted = true;
        platform::write_u32(cursor, platform::read_u32(cursor).wrapping_add(1));
    }

    loop {
        // observed: 72 bytes in the image; one extra byte keeps the
        // terminating NUL inside the array when a field fills the cell.
        let mut field = crate::platform::GuestLocal::new( [0u8; 73]);
        let mut length = 0usize;
        loop {
            let at = platform::read_u32(cursor) as usize;
            let byte = platform::read_u8(source + at);
            if byte == 0x2C
                || byte == 0x22
                || (byte == 0x0D && platform::read_u8(source + at + 1) == 0x0A)
            {
                break;
            }
            field[length] = byte;
            length += 1;
            platform::write_u32(cursor, platform::read_u32(cursor).wrapping_add(1));
        }
        field[length] = 0;

        let slot = manager + platform::read_i32(manager + 0x10) as usize * 0x18;
        if platform::read_u8(slot + 0x15018) != 0x30 {
            let flag = if platform::call2(
                FN_802E1AB4_F,
                field.as_ptr() as u32,
                G_STR_A_F as u32,
            ) == 0
            {
                1u8
            } else if platform::call2(
                FN_802E1AB4_F,
                field.as_ptr() as u32,
                G_STR_B_F as u32,
            ) == 0
            {
                2u8
            } else if platform::call2(
                FN_802E1AB4_F,
                field.as_ptr() as u32,
                G_STR_C_F as u32,
            ) == 0
            {
                4u8
            } else {
                0u8
            };
            if flag != 0 {
                platform::write_u8(
                    slot + 0x1502C,
                    platform::read_u8(slot + 0x1502C) | flag,
                );
            }
        }

        let at = platform::read_u32(cursor) as usize;
        let byte = platform::read_u8(source + at);
        if byte == 0x22 {
            platform::write_u32(cursor, platform::read_u32(cursor).wrapping_add(1));
            break;
        }
        if (!quoted && byte == 0x2C)
            || (byte == 0x0D && platform::read_u8(source + at + 1) == 0x0A)
        {
            break;
        }
        platform::write_u32(cursor, platform::read_u32(cursor).wrapping_add(1));
    }
}

