pub unsafe fn fn_800e8c00(this: usize) {
    let vtable = platform::read_u32(this + 0x2C) as usize;
    let entry = platform::read_u32(vtable + 0x10) as usize;
    let _ = platform::call1(entry, (this + 0x2C) as u32);
    fn_800e8cc0(this);
}

/// Runs the virtual "update" slot of every node in the list widget.
///
/// Walks `count = +0x1C + +0x20` nodes from `+0x24` through the `+0x54`
